163	FUNCTION {output.nonnull.original}
164	{ 's :=
165	  output.state mid.sentence =
166	    { ", " * write$ }
167	    { output.state after.block =
168	        { add.period$ write$
169	          newline$
170	          "\newblock " write$
171	        }
172	        { output.state before.all =
173	            'write$
174	            { add.period$ " " * write$ }
175	          if$
176	        }
177	      if$
178	      mid.sentence 'output.state :=
179	    }
180	  if$
181	  s
182	}
